{"content":"// ============================================================================
// AUTHENTICATION TYPES
// ============================================================================

export interface User {
  id: string
  username: string
  email: string
  role: 'admin' | 'data_scientist' | 'ml_engineer' | 'viewer'
  is_active: boolean
  created_at: string
  last_login: string | null
}

export interface LoginCredentials {
  username: string
  password: string
}

export interface LoginResponse {
  access_token: string
  refresh_token?: string
  token_type: string
  expires_in: number
  user: User
}

export interface RegisterRequest {
  username: string
  email: string
  password: string
  role?: string
}

// ============================================================================
// PAGINATION & BASE RESPONSES
// ============================================================================

export interface PaginationParams {
  page?: number
  page_size?: number
  sort_by?: string
  sort_order?: 'asc' | 'desc'
}

export interface PaginatedResponse<T> {
  items: T[]
  total: number
  page: number
  page_size: number
  pages: number
}

// ============================================================================
// PIPELINE TYPES
// ============================================================================

export interface Pipeline {
  id: string
  name: string
  description: string | null
  config: Record<string, unknown>
  tags: string[]
  is_active: boolean
  created_at: string
  updated_at: string
  created_by: string
  run_count: number
  last_run: Run | null
}

export interface PipelineCreate {
  name: string
  description?: string
  config?: Record<string, unknown>
  tags?: string[]
}

export interface PipelineUpdate {
  name?: string
  description?: string
  config?: Record<string, unknown>
  is_active?: boolean
  tags?: string[]
}

export interface PipelineFilters {
  status?: 'active' | 'inactive' | 'all'
  tag?: string
  search?: string
}

export interface PipelineWithRuns extends Pipeline {
  runs: Run[]
}

// ============================================================================
// RUN TYPES
// ============================================================================

export type RunStatus = 'pending' | 'running' | 'success' | 'failed' | 'cancelled'

export interface Run {
  id: string
  pipeline_id: string
  pipeline_name?: string
  status: RunStatus
  config: Record<string, unknown> | null
  metrics: Record<string, number> | null
  started_at: string | null
  completed_at: string | null
  duration_seconds: number | null
  error_message: string | null
  created_at: string
  triggered_by: string | null
}

export interface RunStep {
  id: string
  run_id: string
  step_name: string
  step_type: string
  status: RunStatus
  started_at: string | null
  completed_at: string | null
  duration_ms: number | null
  logs: string | null
  error_message: string | null
}

export interface RunLog {
  id: string
  run_id: string
  level: 'DEBUG' | 'INFO' | 'WARNING' | 'ERROR'
  message: string
  step: string | null
  timestamp: string
}

export interface RunArtifact {
  id: string
  run_id: string
  name: string
  type: string
  path: string
  size_bytes: number
  metadata: Record<string, unknown> | null
  created_at: string
}

export interface RunCreate {
  pipeline_id: string
  config_override?: Record<string, unknown>
  parameters?: Record<string, unknown>
}

export interface RunFilters extends PaginationParams {
  pipeline_id?: string
  status?: RunStatus
  started_after?: string
  started_before?: string
}

export interface RunMetrics {
  run_id: string
  metrics: Record<string, number | number[]>
  timestamps?: string[]
}

export interface RunComparison {
  run_a: Run
  run_b: Run
  metric_differences: Record<string, number>
  summary: string
}

// ============================================================================
// MODEL TYPES
// ============================================================================

export type ModelFramework = 'sklearn' | 'pytorch' | 'tensorflow' | 'xgboost' | 'catboost' | 'lightgbm' | 'onnx'
export type TaskType = 'classification' | 'regression' | 'clustering' | 'time_series'
export type ModelStage = 'pending' | 'staging' | 'production' | 'archived'

export interface Model {
  id: string
  name: string
  description: string | null
  framework: ModelFramework
  task_type: TaskType
  tags: string[]
  latest_version: number | null
  production_version: number | null
  created_at: string
  updated_at: string
  created_by: string
  total_versions: number
}

export interface ModelVersion {
  id: string
  model_id: string
  version: number
  status: ModelStage
  metrics: Record<string, number> | null
  params: Record<string, unknown> | null
  run_id: string | null
  description: string | null
  created_at: string
  created_by: string | null
}

export interface ModelArtifact {
  id: string
  version_id: string
  type: string
  path: string
  size_bytes: number
  metadata: Record<string, unknown> | null
  created_at: string
}

export interface ModelComparison {
  model_name: string
  version_a: number
  version_b: number
  metric_differences: Record<string, number>
  is_better: boolean
  report: string
}

export interface ModelCreate {
  name: string
  description?: string
  framework: ModelFramework
  task_type: TaskType
  tags?: string[]
}

export interface ModelVersionCreate {
  description?: string
  run_id?: string
  artifact_id?: string
  metrics?: Record<string, number>
  stage?: ModelStage
}

export interface ModelFilters extends PaginationParams {
  framework?: ModelFramework
  task_type?: TaskType
  tag?: string
  search?: string
}

// ============================================================================
// EXPERIMENT TYPES
// ============================================================================

export type ExperimentStatus = 'draft' | 'running' | 'completed' | 'failed' | 'cancelled'

export interface Experiment {
  id: string
  name: string
  description: string | null
  config: Record<string, unknown>
  search_space: Record<string, unknown>
  direction: 'minimize' | 'maximize' | 'unknown'
  metric_name: string | null
  n_trials: number
  status: ExperimentStatus
  best_trial_id: string | null
  created_at: string
  updated_at: string
  created_by: string
  run_count: number
}

export interface Trial {
  id: string
  experiment_id: string
  number: number
  params: Record<string, unknown>
  value: number | null
  intermediate_values: Record<number, number> | null
  status: 'running' | 'completed' | 'pruned' | 'failed'
  started_at: string | null
  completed_at: string | null
}

export interface TrialMetric {
  id: string
  trial_id: string
  step: number
  name: string
  value: number
  timestamp: string
}

export interface ExperimentCreate {
  name: string
  description?: string
  search_space: Record<string, unknown>
  direction?: 'minimize' | 'maximize'
  metric_name?: string
  n_trials?: number
  config?: Record<string, unknown>
}

export interface ExperimentUpdate {
  description?: string
  config?: Record<string, unknown>
}

export interface ExperimentFilters extends PaginationParams {
  tags?: string[]
  search?: string
  status?: ExperimentStatus
}

export interface ExperimentComparisonRequest {
  metric: string
  limit: number
}

export interface ExperimentComparisonResponse {
  experiment_id: string
  metric: string
  runs: Array<{
    id: string
    metric_value: number | null
    params: Record<string, unknown> | null
    started_at: string | null
  }>
}

// ============================================================================
// DRIFT DETECTION TYPES
// ============================================================================

export type DriftMethod = 'psi' | 'ks' | 'chi2' | 'wasserstein' | 'all'
export type DriftStatus = 'no_drift' | 'drift_detected' | 'error'
export type AlertSeverity = 'info' | 'warning' | 'critical'

export interface DriftReport {
  id: string
  model_id: string
  model_version: number
  timestamp: string
  current_dataset_name: string
  reference_dataset_name: string | null
  method: DriftMethod
  drift_detected: boolean
  drift_ratio: number
  threshold: number
