{"path":"/Users/philosopher/active/autopipe/autopipe/dashboard-new/frontend/src/api/client/index.ts","content":"import axios, { 
  AxiosInstance, 
  AxiosRequestConfig, 
  AxiosError,
  InternalAxiosRequestConfig 
} from 'axios'
import { useAuthStore } from '@/stores/authStore'
import toast from 'react-hot-toast'

const API_VERSION = 'v1'

export class ApiClient {
  private client: AxiosInstance
  private baseURL: string

  constructor() {
    this.baseURL = import.meta.env.VITE_API_URL || 'http://localhost:8000/api'

    this.client = axios.create({
      baseURL: `${this.baseURL}/${API_VERSION}`,
      timeout: 30000,
      headers: {
        'Content-Type': 'application/json',
        'Accept': 'application/json',
      },
    })

    this.setupInterceptors()
  }

  private setupInterceptors(): void {
    // Request interceptor - add auth token
    this.client.interceptors.request.use(
      (config: InternalAxiosRequestConfig) => {
        const token = useAuthStore.getState().accessToken
        if (token && config.headers) {
          config.headers.Authorization = `Bearer ${token}`
        }
        return config
      },
      (error) => {
        return Promise.reject(error)
      }
    )

    // Response interceptor - handle errors
    this.client.interceptors.response.use(
      (response) => response,
      (error: AxiosError) => {
        this.handleError(error)
        return Promise.reject(error)
      }
    )
  }

  private handleError(error: AxiosError): void {
    if (!error.response) {
      toast.error('Network error. Please check your connection.')
      return
    }

    const status = error.response.status
    const data = error.response.data as { message?: string; detail?: string }

    switch (status) {
      case 400:
        toast.error(data.message || data.detail || 'Bad request')
        break
      case 401:
        toast.error('Session expired. Please login again.')
        useAuthStore.getState().logout()
        window.location.href = '/login'
        break
      case 403:
        toast.error('You do not have permission to perform this action.')
        break
      case 404:
        toast.error('Resource not found.')
        break
      case 422:
        toast.error(data.message || 'Validation failed')
        break
      case 429:
        toast.error('Too many requests. Please try again later.')
        break
      case 500:
        toast.error('Server error. Please try again later.')
        break
      default:
        toast.error(data.message || 'An unexpected error occurred')
    }
  }

  // Generic request methods
  get<T>(url: string, config?: AxiosRequestConfig): Promise<T> {
    return this.client.get(url, config).then(res => res.data)
  }

  post<T>(url: string, data?: unknown, config?: AxiosRequestConfig): Promise<T> {
    return this.client.post(url, data, config).then(res => res.data)
  }

  put<T>(url: string, data?: unknown, config?: AxiosRequestConfig): Promise<T> {
    return this.client.put(url, data, config).then(res => res.data)
  }

  patch<T>(url: string, data?: unknown, config?: AxiosRequestConfig): Promise<T> {
    return this.client.patch(url, data, config).then(res => res.data)
  }

  delete<T>(url: string, config?: AxiosRequestConfig): Promise<T> {
    return this.client.delete(url, config).then(res => res.data)
  }

  // File upload helper
  uploadFile<T>(url: string, file: File, fieldName: string = 'file', additionalData?: Record<string, unknown>): Promise<T> {
    const formData = new FormData()
    formData.append(fieldName, file)

    if (additionalData) {
      Object.entries(additionalData).forEach(([key, value]) => {
        formData.append(key, String(value))
      })
    }

    return this.client.post(url, formData, {
      headers: {
        'Content-Type': 'multipart/form-data',
      },
    }).then(res => res.data)
  }

  // Download helper
  download(url: string, filename?: string): void {
    this.client.get(url, { responseType: 'blob' }).then((response) => {
      const blob = new Blob([response.data])
      const link = document.createElement('a')
      link.href = window.URL.createObjectURL(blob)
      if (filename) link.download = filename
      link.click()
      window.URL.revokeObjectURL(link.href)
    })
  }
}

// Singleton instance
export const apiClient = new ApiClient()

// Export for direct use in TanStack Query
export const queryFn = async <T>(
  url: string,
  options?: AxiosRequestConfig
): Promise<T> => {
  return apiClient.get<T>(url, options)
}

// Mutation helpers
export const mutationFn = {
  post: <T>(url: string) => (data: unknown) => apiClient.post<T>(url, data),
  put: <T>(url: string) => (data: unknown) => apiClient.put<T>(url, data),
  patch: <T>(url: string) => (data: unknown) => apiClient.patch<T>(url, data),
  delete: <T>(url: string) => () => apiClient.delete<T>(url),
}
"}

