{"path":"/Users/philosopher/active/autopipe/autopipe/dashboard-new/frontend/src/api/endpoints/websocket.ts","content":"import { io, Socket } from 'socket.io-client'
import { useAuthStore } from '@/stores/authStore'
import type { 
  WebSocketMessage, 
  RunWebSocketMessage, 
  DashboardWebSocketMessage 
} from '@/types'

const WS_URL = import.meta.env.VITE_WS_URL || 'http://localhost:8000'

class WebSocketService {
  private socket: Socket | null = null
  private runningSockets: Map<string, Socket> = new Map()

  // Callbacks
  private onDashboardUpdate?: (data: DashboardWebSocketMessage['payload']) => void
  private onRunUpdate?: (data: RunWebSocketMessage['payload']) => void
  private onLogMessage?: (data: { run_id: string; logs: string[] }) => void

  /**
   * Connect to the dashboard WebSocket for real-time updates
   */
  connectDashboard(
    onUpdate?: (data: DashboardWebSocketMessage['payload']) => void,
    options?: { 
      onConnect?: () => void
      onDisconnect?: () => void
      onError?: (error: Error) => void
    }
  ): Socket {
    this.onDashboardUpdate = onUpdate
    const authStore = useAuthStore.getState()

    this.socket = io(`${WS_URL}/ws/dashboard`, {
      auth: {
        token: authStore.accessToken,
      },
      transports: ['websocket'],
    })

    this.socket.on('connect', () => {
      console.log('WebSocket connected')
      options?.onConnect?.()
    })

    this.socket.on('disconnect', () => {
      console.log('WebSocket disconnected')
      options?.onDisconnect?.()
    })

    this.socket.on('connect_error', (error) => {
      console.error('WebSocket connection error:', error)
      options?.onError?.(error)
    })

    this.socket.on('dashboard_update', (data: DashboardWebSocketMessage['payload']) => {
      this.onDashboardUpdate?.(data)
    })

    return this.socket
  }

  /**
   * Connect to a run-specific WebSocket for real-time logs and metrics
   */
  connectRun(
    runId: string,
    callbacks: {
      onStatus?: (data: { run_id: string; status: string }) => void
      onLogs?: (data: { run_id: string; logs: string[] }) => void
      onMetrics?: (data: { run_id: string; metrics: Record<string, number> }) => void
      onComplete?: (data: { run_id: string; status: string }) => void
      onError?: (error: Error) => void
    }
  ): Socket {
    const authStore = useAuthStore.getState()

    const socket = io(`${WS_URL}/ws/runs/${runId}`, {
      auth: {
        token: authStore.accessToken,
      },
      transports: ['websocket'],
    })

    socket.on('run_update', (data) => {
      callbacks?.onStatus?.(data)
    })

    socket.on('run_log', (data) => {
      callbacks?.onLogs?.(data)
    })

    socket.on('run_metrics', (data) => {
      callbacks?.onMetrics?.(data)
    })

    socket.on('run_complete', (data) => {
      callbacks?.onComplete?.(data)
    })

    socket.on('connect_error', (error) => {
      callbacks?.onError?.(error)
    })

    this.runningSockets.set(runId, socket)
    return socket
  }

  /**
   * Disconnect from the dashboard WebSocket
   */
  disconnectDashboard(): void {
    this.socket?.disconnect()
    this.socket = null
    this.onDashboardUpdate = undefined
    this.onRunUpdate = undefined
  }

  /**
   * Disconnect from a run-specific WebSocket
   */
  disconnectRun(runId: string): void {
    const socket = this.runningSockets.get(runId)
    if (socket) {
      socket.disconnect()
      this.runningSockets.delete(runId)
    }
  }

  /**
   * Disconnect all WebSockets
   */
  disconnectAll(): void {
    this.disconnectDashboard()
    this.runningSockets.forEach((socket) => {
      socket.disconnect()
    })
    this.runningSockets.clear()
  }

  /**
   * Subscribe to global system events
   */
  subscribeToEvents(
    event: 'system_alert' | 'experiment_complete' | 'drift_detected',
    callback: (data: unknown) => void
  ): () => void {
    if (!this.socket) {
      console.warn('WebSocket not connected')
      return () => {}
    }

    this.socket.on(event, callback)

    // Return unsubscribe function
    return () => {
      this.socket?.off(event, callback)
    }
  }

  /**
   * Check if dashboard connection is active
   */
  isConnected(): boolean {
    return this.socket?.connected || false
  }

  /**
   * Reconnect to dashboard WebSocket
   */
  reconnect(): void {
    if (this.socket) {
      this.socket.connect()
    }
  }
}

export const websocketService = new WebSocketService()
"}

{"content":"import { create } from 'zustand'
import { persist } from 'zustand/middleware'
import type { User, LoginResponse } from '@/types'

interface AuthState {
  // State
  user: User | null
  accessToken: string | null
  refreshToken: string | null
  isAuthenticated: boolean
  isLoading: boolean

  // Actions
  setUser: (user: User | null) => void
  setTokens: (tokens: { accessToken: string; refreshToken?: string }) => void
  login: (response: LoginResponse) => void
  logout: () => void
  setLoading: (loading: boolean) => void
  updateUser: (user: Partial<User>) => void
}

export const useAuthStore = create<AuthState>()(
  persist(
    (set, get) => ({
      // Initial state
      user: null,
      accessToken: null,
      refreshToken: null,
      isAuthenticated: false,
      isLoading: false,

      // Actions
      setUser: (user) => {
        set({ 
          user, 
          isAuthenticated: !!user 
        })
      },

      setTokens: ({ accessToken, refreshToken }) => {
        set({ 
          accessToken, 
          refreshToken: refreshToken || get().refreshToken 
        })
      },

      login: (response) => {
        set({
          user: response.user,
          accessToken: response.access_token,
          refreshToken: response.refresh_token || null,
          isAuthenticated: true,
          isLoading: false,
        })
      },

      logout: () => {
        // Don't clear loading state on logout
        set({
          user: null,
          accessToken: null,
          refreshToken: null,
          isAuthenticated: false,
        })
      },

      setLoading: (loading) => {
        set({ isLoading: loading })
      },

      updateUser: (updates) => {
        const currentUser = get().user
        if (currentUser) {
          set({ user: { ...currentUser, ...updates } })
        }
      },
    }),
    {
      name: 'autopipe-auth-storage',
      partialize: (state) => ({
        accessToken: state.accessToken,
        refreshToken: state.refreshToken,
        user: state.user,
        isAuthenticated: state.isAuthenticated,
      }),
    }
  )
)
