{"content":"import { create } from 'zustand'
import { persist } from 'zustand/middleware'
import type { ThemeSettings } from '@/types'

type Theme = 'light' | 'dark' | 'system'

interface UIState {
  // Theme
  theme: Theme
  accentColor: ThemeSettings['accentColor']
  sidebarCollapsed: boolean

  // Notifications
  notifications: Array<{
    id: string
    type: 'info' | 'success' | 'warning' | 'error'
    title: string
    message: string
    dismissed: boolean
  }>

  // Loading states
  activeRequests: number

  // Actions
  setTheme: (theme: Theme) => void
  setAccentColor: (color: ThemeSettings['accentColor']) => void
  toggleSidebar: () => void
  addNotification: (notification: Omit<UIState['notifications'][0], 'id' | 'dismissed'>) => string
  dismissNotification: (id: string) => void
  clearNotifications: () => void
  incrementRequests: () => void
  decrementRequests: () => void
}

export const useUIStore = create<UIState>()(
  persist(
    (set, get) => ({
      // Initial state
      theme: 'system',
      accentColor: 'blue',
      sidebarCollapsed: false,
      notifications: [],
      activeRequests: 0,

      // Actions
      setTheme: (theme) => {
        set({ theme })
        applyTheme(theme)
      },

      setAccentColor: (accentColor) => {
        set({ accentColor })
      },

      toggleSidebar: () => {
        set((state) => ({ sidebarCollapsed: !state.sidebarCollapsed }))
      },

      addNotification: (notification) => {
        const id = `notif-${Date.now()}-${Math.random()}`
        set((state) => ({
          notifications: [
            { ...notification, id, dismissed: false },
            ...state.notifications.slice(0, 9), // Keep last 10
          ],
        }))
        return id
      },

      dismissNotification: (id) => {
        set((state) => ({
          notifications: state.notifications.map((n) =>
            n.id === id ? { ...n, dismissed: true } : n
          ),
        }))
      },

      clearNotifications: () => {
        set({ notifications: [] })
      },

      incrementRequests: () => {
        set((state) => ({ activeRequests: state.activeRequests + 1 }))
      },

      decrementRequests: () => {
        set((state) => ({ 
          activeRequests: Math.max(0, state.activeRequests - 1) 
        }))
      },
    }),
    {
      name: 'autopipe-ui-storage',
      partialize: (state) => ({
        theme: state.theme,
        accentColor: state.accentColor,
        sidebarCollapsed: state.sidebarCollapsed,
      }),
    }
  )
)

// Helper function to apply theme
function applyTheme(theme: Theme): void {
  const root = document.documentElement
  root.classList.remove('light', 'dark')

  if (theme === 'system') {
    const systemTheme = window.matchMedia('(prefers-color-scheme: dark)').matches
      ? 'dark'
      : 'light'
    root.classList.add(systemTheme)
  } else {
    root.classList.add(theme)
  }
}

// Initialize theme on load
export function initTheme(): void {
  const savedTheme = useUIStore.getState().theme
  applyTheme(savedTheme)

  // Listen for system theme changes
  window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', (e) => {
    if (useUIStore.getState().theme === 'system') {
      applyTheme('system')
    }
  })
}
