{"content":"import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'

/**
 * Combines multiple class names using clsx and tailwind-merge
 * for conditional Tailwind CSS classes
 */
export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs))
}

/**
 * Format a date to a readable string
 */
export function formatDate(date: string | Date | null, options?: Intl.DateTimeFormatOptions): string {
  if (!date) return 'N/A'

  const d = typeof date === 'string' ? new Date(date) : date
  const defaultOptions: Intl.DateTimeFormatOptions = {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    ...options,
  }

  return d.toLocaleDateString('en-US', defaultOptions)
}

/**
 * Format a date as relative time (e.g., "2 hours ago")
 */
export function formatRelativeTime(date: string | Date | null): string {
  if (!date) return 'N/A'

  const d = typeof date === 'string' ? new Date(date) : date
  const now = new Date()
  const diff = now.getTime() - d.getTime()

  const seconds = Math.floor(diff / 1000)
  const minutes = Math.floor(seconds / 60)
  const hours = Math.floor(minutes / 60)
  const days = Math.floor(hours / 24)
  const weeks = Math.floor(days / 7)
  const months = Math.floor(days / 30)
  const years = Math.floor(days / 365)

  if (seconds < 60) return 'just now'
  if (minutes < 60) return `${minutes}m ago`
  if (hours < 24) return `${hours}h ago`
  if (days < 7) return `${days}d ago`
  if (weeks < 4) return `${weeks}w ago`
  if (months < 12) return `${months}mo ago`
  return `${years}y ago`
}

/**
 * Format bytes to human readable size
 */
export function formatBytes(bytes: number, decimals = 2): string {
  if (bytes === 0) return '0 Bytes'

  const k = 1024
  const dm = decimals < 0 ? 0 : decimals
  const sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB', 'PB']

  const i = Math.floor(Math.log(bytes) / Math.log(k))

  return `${parseFloat((bytes / Math.pow(k, i)).toFixed(dm))} ${sizes[i]}`
}

/**
 * Format a number with appropriate suffix
 */
export function formatNumber(num: number): string {
  if (num >= 1000000) {
    return `${(num / 1000000).toFixed(1)}M`
  }
  if (num >= 1000) {
    return `${(num / 1000).toFixed(1)}K`
  }
  return num.toString()
}

/**
 * Format duration in seconds to human readable string
 */
export function formatDuration(seconds: number | null): string {
  if (seconds === null || seconds === undefined) return 'N/A'

  const hours = Math.floor(seconds / 3600)
  const minutes = Math.floor((seconds % 3600) / 60)
  const secs = Math.floor(seconds % 60)

  if (hours > 0) {
    return `${hours}h ${minutes}m ${secs}s`
  }
  if (minutes > 0) {
    return `${minutes}m ${secs}s`
  }
  return `${secs}s`
}

/**
 * Truncate a string with ellipsis
 */
export function truncate(str: string, length: number): string {
  if (str.length <= length) return str
  return `${str.slice(0, length)}...`
}

/**
 * Debounce a function
 */
export function debounce<T extends (...args: unknown[]) => unknown>(
  fn: T,
  delay: number
): (...args: Parameters<T>) => void {
  let timeoutId: ReturnType<typeof setTimeout>
  return (...args: Parameters<T>) => {
    clearTimeout(timeoutId)
    timeoutId = setTimeout(() => fn(...args), delay)
  }
}

/**
 * Generate a unique ID
 */
export function generateId(): string {
  return `id_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`
}

/**
 * Validate email format
 */
export function isValidEmail(email: string): boolean {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
  return emailRegex.test(email)
}

/**
 * Get status color for different statuses
 */
export function getStatusColor(status: string): string {
  const colors: Record<string, string> = {
    // Runs
    pending: 'text-yellow-500 bg-yellow-50 border-yellow-200',
    running: 'text-blue-500 bg-blue-50 border-blue-200 animate-pulse',
    success: 'text-green-500 bg-green-50 border-green-200',
    failed: 'text-red-500 bg-red-50 border-red-200',
    cancelled: 'text-gray-500 bg-gray-50 border-gray-200',
    completed: 'text-green-500 bg-green-50 border-green-200',

    // Models
    production: 'text-purple-500 bg-purple-50 border-purple-200',
    staging: 'text-orange-500 bg-orange-50 border-orange-200',
    archived: 'text-gray-500 bg-gray-50 border-gray-200',

    // Alerts
    info: 'text-blue-500 bg-blue-50',
    warning: 'text-orange-500 bg-orange-50',
    critical: 'text-red-500 bg-red-50',
  }

  return colors[status.toLowerCase()] || 'text-gray-500 bg-gray-50 border-gray-200'
}

/**
 * Get status icon name for different statuses
 */
export function getStatusIcon(status: string): string {
  const icons: Record<string, string> = {
    pending: 'Clock',
    running: 'Loader2',
    success: 'CheckCircle',
    completed: 'CheckCircle',
    failed: 'XCircle',
    cancelled: 'AlertCircle',
    production: 'Rocket',
    staging: 'FlaskConical',
    archived: 'Archive',
    info: 'Info',
    warning: 'AlertTriangle',
    critical: 'AlertOctagon',
  }

  return icons[status.toLowerCase()] || 'Circle'
}
