{"content":"import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom'
import { useEffect } from 'react'
import { useAuthStore } from './stores/authStore'
import { websocketService } from './api/endpoints/websocket'

// Layout
import DashboardLayout from './components/layout/Layout'
import ProtectedRoute from './components/auth/ProtectedRoute'

// Pages
import Login from './pages/auth/Login'
import Dashboard from './pages/dashboard/Dashboard'
import PipelineList from './pages/pipelines/PipelineList'
import PipelineDetail from './pages/pipelines/PipelineDetail'
import RunList from './pages/runs/RunList'
import RunDetail from './pages/runs/RunDetail'
import ModelList from './pages/models/ModelList'
import ModelDetail from './pages/models/ModelDetail'
import ExperimentList from './pages/experiments/ExperimentList'
import ExperimentDetail from './pages/experiments/ExperimentDetail'
import DriftList from './pages/drift/DriftList'
import DriftReport from './pages/drift/DriftReport'
import Settings from './pages/settings/Settings'
import Team from './pages/settings/Team'
import NotFound from './pages/NotFound'

function App() {
  const { isAuthenticated } = useAuthStore()

  // Initialize WebSocket on mount
  useEffect(() => {
    if (isAuthenticated) {
      websocketService.connectDashboard()
    }

    return () => {
      websocketService.disconnectAll()
    }
  }, [isAuthenticated])

  return (
    <Router>
      <Routes>
        {/* Public Routes */}
        <Route path="/login" element={<Login />} />

        {/* Protected Routes */}
        <Route element={<ProtectedRoute />}>
          <Route element={<DashboardLayout />}>
            {/* Dashboard */}
            <Route path="/" element={<Navigate to="/dashboard" />} />
            <Route path="/dashboard" element={<Dashboard />} />

            {/* Pipelines */}
            <Route path="/pipelines" element={<PipelineList />} />
            <Route path="/pipelines/:id" element={<PipelineDetail />} />

            {/* Runs */}
            <Route path="/runs" element={<RunList />} />
            <Route path="/runs/:id" element={<RunDetail />} />

            {/* Models */}
            <Route path="/models" element={<ModelList />} />
            <Route path="/models/:id" element={<ModelDetail />} />

            {/* Experiments */}
            <Route path="/experiments" element={<ExperimentList />} />
            <Route path="/experiments/:id" element={<ExperimentDetail />} />

            {/* Drift Detection */}
            <Route path="/drift" element={<DriftList />} />
            <Route path="/drift/:id" element={<DriftReport />} />

            {/* Settings */}
            <Route path="/settings" element={<Navigate to="/settings/general" />} />
            <Route path="/settings/general" element={<Settings />} />
            <Route path="/settings/team" element={<Team />} />
          </Route>
        </Route>

        {/* 404 */}
        <Route path="*" element={<NotFound />} />
      </Routes>
    </Router>
  )
}

export default App
