{"content":"import { Link } from 'react-router-dom'
import { Activity, Users, PieChart, AlertTriangle } from 'lucide-react'
import { useQuery } from '@tanstack/react-query'
import { dashboardApi } from '@/api/endpoints'
import { formatNumber } from '@/lib/utils'

export default function DashboardPage() {
  const { data: stats } = useQuery({
    queryKey: ['dashboard', 'stats'],
    queryFn: dashboardApi.getOverview,
  })

  const { data: activity } = useQuery({
    queryKey: ['dashboard', 'activity'],
    queryFn: () => dashboardApi.getActivity({ page_size: 5 }),
  })

  return (
    <div className="p-6">
      <h1 className="text-2xl font-bold mb-6">Dashboard</h1>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
        <StatCard
          icon={<Activity className="h-8 w-8 text-blue-600" />}
          title="Pipelines"
          value={formatNumber(stats?.pipelines?.total ?? 0)}
          subtitle={`${stats?.pipelines?.running ?? 0} running`}
          link="/pipelines"
        />
        <StatCard
          icon={<Users className="h-8 w-8 text-green-600" />}
          title="Models"
          value={formatNumber(stats?.models?.total ?? 0)}
          subtitle={`${stats?.models?.in_production ?? 0} in production`}
          link="/models"
        />
        <StatCard
          icon={<PieChart className="h-8 w-8 text-purple-600" />}
          title="Experiments"
          value={formatNumber(stats?.experiments?.active ?? 0)}
          subtitle={`${stats?.experiments?.completed_today ?? 0} completed today`}
          link="/experiments"
        />
        <StatCard
          icon={<AlertTriangle className="h-8 w-8 text-orange-600" />}
          title="Drift Detected"
          value={stats?.drift?.features_drifted ?? 0}
          subtitle={`${((stats?.drift?.drift_ratio ?? 0) * 100).toFixed(1)}% drift ratio`}
          link="/drift"
        />
      </div>

      {/* Activity Feed */}
      <div className="bg-white rounded-lg shadow p-6">
        <h2 className="text-lg font-semibold mb-4">Recent Activity</h2>
        <div className="space-y-4">
          {activity?.items?.map((item) => (
            <div key={item.id} className="flex items-center space-x-3 py-2 border-b last:border-0">
              <div className="flex-1">
                <p className="font-medium">{item.title}</p>
                <p className="text-sm text-gray-500">{item.description}</p>
              </div>
              <span className="text-sm text-gray-400">
                {new Date(item.timestamp).toLocaleString()}
              </span>
            </div>
          ))}
          {!activity?.items?.length && (
            <p className="text-gray-500 text-center py-8">No recent activity</p>
          )}
        </div>
      </div>
    </div>
  )
}

interface StatCardProps {
  icon: React.ReactNode
  title: string
  value: string | number
  subtitle: string
  link: string
}

function StatCard({ icon, title, value, subtitle, link }: StatCardProps) {
  return (
    <Link
      to={link}
      className="bg-white rounded-lg shadow p-6 hover:shadow-md transition-shadow"
    >
      <div className="flex items-center justify-between">
        <div>{icon}</div>
        <div className="text-right">
          <p className="text-3xl font-bold">{value}</p>
          <p className="text-sm text-gray-500 capitalize">{title}</p>
        </div>
      </div>
      <p className="text-sm text-gray-600 mt-2">{subtitle}</p>
    </Link>
  )
}
